const input = $('Pacing update webhook').item.json.body;
const { callOutcome } = input;
const campaign = $('Fetch Campaign').item.json;

// 300bp (3%) is the FTC TSR's own abandonment-rate ceiling, seeded as the default target -
// flagged for compliance-owner/counsel confirmation before launch (CRM-OBJECT-MODEL.md's
// Compliance layer section), same treatment as every other legally-consequential default here.
const targetBp = campaign.targetAbandonmentRateBp ?? 300;
const ceiling = campaign.maxSimultaneousCallsPerAgentCeiling ?? 1;
const currentAllowed = campaign.currentAllowedSimultaneousCallsPerAgent ?? ceiling;
const priorRateBp = campaign.rollingAbandonmentRate ?? 0;

// Only Connected/Abandoned outcomes are pacing-relevant - a NoAnswer/Busy/etc never reached a
// live person, so it never counts toward an abandonment rate at all.
if (callOutcome !== 'Connected' && callOutcome !== 'Abandoned') {
  return [{
    json: {
      changed: false,
      action: 'IGNORED',
      rollingAbandonmentRate: priorRateBp,
      currentAllowedSimultaneousCallsPerAgent: currentAllowed,
      reason: `callOutcome "${callOutcome}" isn't pacing-relevant (not Connected or Abandoned) - no update.`,
    },
  }];
}

// Exponential moving average, not a true rolling window - there's no per-call event log to
// average over yet (Communications Hub, W2.5, isn't built). Weights the newest outcome at 5%,
// smooths out single-call noise while still reacting within a few dozen calls. Revisit once real
// call-event history exists to compute a true windowed rate instead of this approximation.
const ALPHA = 0.05;
const outcomeBp = callOutcome === 'Abandoned' ? 10000 : 0;
const newRateBp = Math.round(priorRateBp * (1 - ALPHA) + outcomeBp * ALPHA);

let newAllowed = currentAllowed;
let action = 'HOLD';
if (newRateBp > targetBp) {
  newAllowed = Math.max(1, currentAllowed - 1);
  action = 'THROTTLE_DOWN';
} else if (newRateBp < targetBp * 0.5 && currentAllowed < ceiling) {
  newAllowed = Math.min(ceiling, currentAllowed + 1);
  action = 'RAMP_UP';
}

return [{
  json: {
    changed: true,
    action,
    rollingAbandonmentRate: newRateBp,
    targetAbandonmentRateBp: targetBp,
    currentAllowedSimultaneousCallsPerAgent: newAllowed,
    maxSimultaneousCallsPerAgentCeiling: ceiling,
    reason: `${action} - rolling rate ${newRateBp}bp vs target ${targetBp}bp.`,
  },
}];
